/* Terms of use, privacy and data-source pages in German, Italian and Spanish. Loaded after legal.js.
   The English version prevails if the versions differ. */
"use strict";
(() => {
  const L = (arr, i) => (arr && arr[i] != null ? arr[i] : arr && arr[0]);
  const sup = i => L(COUNTRY.support[AREA] || COUNTRY.support.other, i);
  const cri = i => L(COUNTRY.crisis || [""], i);
  const em = () => COUNTRY.emergency || "112";
  const built = () => META ? fmtDate(META.built.slice(0, 10)) : "…";
  const mapName = () => MAP.mapboxToken ? "Mapbox" : "OpenStreetMap";

  LEGAL.de = {
terms: () => `<h2>Nutzungsbedingungen</h2>
<p class="lede"><b>Gültig ab: 23. November 2026.</b> Bitte lesen Sie diese Bedingungen sorgfältig. Bei Abweichungen zwischen den Sprachfassungen gilt die englische Fassung.</p>
<p>Find My Trial™ ist ein Suchdienst für klinische Studien, betrieben von ${esc(ORG.name)} („wir“, „uns“), der derzeit als Pilot angeboten wird. Indem Sie das Kästchen auf der Startseite ankreuzen oder Find My Trial™ aufrufen oder nutzen, bestätigen Sie, dass Sie diese Bedingungen gelesen und verstanden haben und ihnen zustimmen. Wenn Sie nicht zustimmen, nutzen Sie Find My Trial™ nicht.</p>
<ol>
<li><b>Was Find My Trial™ ist.</b> Find My Trial™ ist ein Pilotdienst. Er steht Privatpersonen sowie Unternehmen und anderen Organisationen offen und wird laufend verbessert; Funktionen können ohne Ankündigung hinzukommen, sich ändern oder wegfallen. Er ist ein Informationswerkzeug, um klinische Studien zu finden und mit einer Ärztin, einem Arzt oder einem Studienteam zu besprechen, und darf nicht die einzige Grundlage für medizinische, therapeutische, wissenschaftliche, rechtliche oder andere wichtige Entscheidungen sein. Es listet Studien ${L(A.about, 2)}, die rekrutieren oder bald rekrutieren und mindestens ein Zentrum ${COUNTRY.inName[2]} haben, wie auf ${REGS(2)} veröffentlicht. Die Liste wird einmal täglich automatisch aktualisiert; die Seite zeigt das Datum der letzten Aktualisierung. Studien, die nicht auf ${REGS(2)} registriert sind, fehlen, daher kann die Liste unvollständig sein, und die Angaben zu einer Studie können sich seit der letzten Aktualisierung geändert haben.</li>
<li><b>Pilotdienst und Ihre Risiken.</b> Wir können den Zugang zu Find My Trial™ jederzeit mit oder ohne Ankündigung einschränken, aussetzen oder beenden. Mit der Nutzung akzeptieren Sie, dass Find My Trial™
 <ul><li>als Pilotdienst Fehler, Mängel oder unvollständige Funktionen enthalten kann;</li>
 <li>falsche, unvollständige, irreführende oder veraltete Informationen anzeigen kann;</li>
 <li>jederzeit nicht verfügbar sein kann; und</li>
 <li>wir ihn ändern, pausieren oder einstellen können und Unterstützung in unserem Ermessen liegt, sofern nicht schriftlich anders vereinbart.</li></ul>
 <b>Sie nutzen Find My Trial™ auf eigenes Risiko.</b></li>
<li><b>Keine medizinische, rechtliche oder fachliche Beratung.</b> Find My Trial™ bietet keine medizinische, klinische, wissenschaftliche, rechtliche, regulatorische oder sonstige fachliche Beratung. Treffer, Reihenfolgen, Zusammenfassungen und andere Ergebnisse dienen nur der Information. Ein Treffer bedeutet nicht, dass Sie für eine Studie infrage kommen, und ein Ausschluss bedeutet nicht, dass Sie ungeeignet sind: Nur ein Studienteam kann darüber entscheiden, nachdem es Ihre vollständige Krankengeschichte und das vollständige Protokoll geprüft hat. Find My Trial™ empfiehlt oder befürwortet keine Studie, und Studieninformationen können veraltet sein. Sie sind dafür verantwortlich, alles zu prüfen, bevor Sie danach handeln. <b>Sprechen Sie immer mit Ihrer Ärztin, Ihrem Arzt oder anderem qualifiziertem Gesundheitspersonal, bevor Sie eine Entscheidung über eine klinische Studie oder Ihre Behandlung treffen.</b> Find My Trial™ kann nicht auf Notfälle reagieren: Bei dringenden Beschwerden rufen Sie ${em()} an oder gehen Sie in die nächste Notaufnahme. ${sup(2)} ${cri(2)}</li>
<li><b>Automatische Zuordnung und KI-gestützte Inhalte.</b> Find My Trial™ filtert Studien anhand der Registerangaben und fester, automatischer Regeln. ${L(A.tagged, 2)} automatisch aus dem Registertext erkannt und können falsch sein. Wo Find My Trial™ eine persönliche Prüfung der Teilnahmekriterien zeigt, wurden die Kriterien von KI-Werkzeugen gelesen und nicht von Fachpersonal überprüft. Ergebnisse und Inhalte können daher falsch, unvollständig, veraltet oder widersprüchlich sein und sollten nicht ohne Prüfung des ursprünglichen Registereintrags und Rücksprache mit dem Studienteam verwendet werden. Wir garantieren nicht, dass Ergebnisse oder Inhalte richtig, vollständig, zuverlässig oder für Ihre Zwecke geeignet sind, und wir befürworten keine Dienstleistung, kein Produkt und keine Behandlung.</li>
<li><b>Zulässige Nutzung.</b> Sie verpflichten sich, Find My Trial™ nicht
 <ul><li>für rechtswidrige Zwecke zu nutzen;</li>
 <li>unbefugt auf damit verbundene Konten, Systeme oder Daten zuzugreifen;</li>
 <li>mit Viren, Schadsoftware oder anderem schädlichem Code zu belasten;</li>
 <li>in seiner Funktion zu stören oder Zugangskontrollen oder technische Grenzen zu umgehen;</li>
 <li>zurückzuentwickeln, zu dekompilieren oder zu zerlegen, soweit das Gesetz es nicht erlaubt oder wir nicht schriftlich zustimmen;</li>
 <li>ohne unsere schriftliche Zustimmung systematisch auszulesen oder mit Bots oder automatisierten Werkzeugen zu nutzen;</li>
 <li>ohne unsere schriftliche Zustimmung Sicherheits-, Schwachstellen- oder Penetrationstests zu unterziehen; oder</li>
 <li>auf eine Weise zu nutzen, die seine Sicherheit, Integrität oder Verfügbarkeit beeinträchtigen könnte.</li></ul></li>
<li><b>Rückmeldungen.</b> Wir freuen uns über Kommentare, Vorschläge, Fehlermeldungen und andere Rückmeldungen („Feedback“) an ${contactHTML()}. Sie sind für das verantwortlich, was Sie uns senden, und bestätigen, dass Sie es teilen dürfen. Sie räumen uns eine unbefristete, unwiderrufliche, weltweite, unentgeltliche, übertragbare und unterlizenzierbare Lizenz ein, Feedback zu nutzen, zu kopieren, zu ändern, weiterzugeben und anderweitig zu verwerten, auch kommerziell, ohne Vergütung, Nennung oder weitere Zustimmung. Bitte senden Sie keine Gesundheitsdaten oder anderen sensiblen personenbezogenen Daten. Personenbezogene Daten, die Sie dennoch angeben, werden wie in Abschnitt 7 beschrieben behandelt.</li>
<li><b>Datenschutz.</b> Ihre Antworten auf die Fragen von Find My Trial™ und Ihr Standort, falls Sie „Meinen Standort verwenden“ wählen, werden nur in Ihrem Browser verarbeitet. Wir erheben, speichern oder erhalten sie nicht, und sie werden an keinen KI-Dienst gesendet. Für die Straßenkarte lädt Ihr Browser Kartenbilder von unserem Kartenanbieter, der dabei Ihre IP-Adresse und Browserangaben nach seiner eigenen Datenschutzerklärung erhält, aber nie Ihre Antworten. Wenn Sie uns Feedback senden, das Sie identifiziert, dürfen wir es erheben, nutzen, speichern und auswerten, um Find My Trial™ zu bewerten, zu pflegen, zu verbessern und weiterzuentwickeln, für interne Forschung und Qualitätsprüfung und zur Dokumentation von Tests. Die Seite „Datenschutz“ enthält weitere Einzelheiten.</li>
<li><b>Geistiges Eigentum.</b> Gestaltung, Texte, Code und zugehörige Materialien von Find My Trial™ gehören ${esc(ORG.name)} oder seinen Lizenzgebern und sind rechtlich geschützt. Studieninformationen gehören dem jeweiligen Register und den Sponsoren. Kartendaten © OpenStreetMap-Mitwirkende${MAP.mapboxToken ? ", Kartenstil © Mapbox" : ""}; die Karte nutzt die quelloffene Bibliothek Leaflet unter deren eigener Lizenz. Es geht kein Eigentum auf Sie über. Vorbehaltlich dieser Bedingungen erhalten Sie ein beschränktes, widerrufliches, nicht ausschließliches und nicht übertragbares Recht, Find My Trial™ zu nutzen, um Informationen über klinische Studien zu suchen und anzusehen, für sich selbst oder innerhalb Ihres Unternehmens oder Ihrer Organisation, auch zu geschäftlichen Zwecken. Weiterverkauf, Wiederveröffentlichung oder Weitergabe von Find My Trial™ oder seinen Inhalten sowie deren Nutzung für ein anderes Produkt, einen anderen Dienst oder Datenbestand erfordern eine gesonderte schriftliche Vereinbarung mit uns. <b>Forschung und Zitierung.</b> Wenn Sie über Find My Trial™ gefundene Informationen in Forschung, einer Veröffentlichung, einem Bericht oder einem Vortrag verwenden, müssen Sie sie so zitieren: „Quelle: Find My Trial™, Salish Seven LLC (abgerufen am [Datum])“, zusammen mit den ursprünglichen Studienregistern. Auswahl, Aufbereitung, Einordnung und Übersetzung der Studieninformationen sind das Werk der Salish Seven LLC, die deren Urheberin und Eigentümerin bleibt; durch die Nutzung gehen diese Urheberschaft und dieses Eigentum nicht auf Sie über. Die massenhafte Extraktion oder Auswertung von Daten aus Find My Trial™ für Forschungszwecke erfordert eine schriftliche Vereinbarung mit uns.</li>
<li><b>Vertrauliche Informationen.</b> Wenn wir Ihnen nicht öffentliches Material direkt überlassen, etwa neue Funktionen, Dokumente oder Leistungsdaten für Pilotteilnehmende oder Geschäftspartner, geben Sie es ohne unsere schriftliche Zustimmung an niemanden weiter. Dies gilt nicht für Informationen, die ohne Verstoß gegen diese Bedingungen öffentlich werden, die Sie rechtmäßig bereits kannten oder die Sie gesetzlich offenlegen müssen.</li>
<li><b>Aussetzung und Beendigung.</b> Wir können Ihren Zugang jederzeit mit oder ohne Ankündigung aussetzen oder beenden. Mit dem Ende des Zugangs endet Ihr Recht zur Nutzung sofort. Die Abschnitte 6, 8, 9, 11, 12 und 14 gelten danach weiter.</li>
<li><b>Keine Gewährleistung.</b> Find My Trial™ wird „wie besehen“, „wie verfügbar“ und „mit allen Mängeln“ bereitgestellt. Wir geben keine ausdrücklichen oder stillschweigenden Zusicherungen, dass er richtig, vollständig, fehlerfrei, sicher, mangelfrei oder für einen bestimmten Zweck geeignet ist. Zwingende gesetzliche Rechte, die Ihnen als Verbraucherin oder Verbraucher zustehen, bleiben unberührt.</li>
<li><b>Haftungsbeschränkung und Freistellung.</b> Soweit gesetzlich zulässig, haften ${esc(ORG.name)} und seine Geschäftsführung, Mitglieder, Freiwilligen, Mitwirkenden, Beauftragten und Lizenzgeber (die „${esc(ORG.name)}-Parteien“) nicht für direkte, indirekte, besondere, zufällige oder Folgeschäden jeglicher Art, einschließlich entgangenen Gewinns oder anderer finanzieller Verluste, die aus der Nutzung oder Nichtnutzbarkeit von Find My Trial™ oder verlinkter Websites entstehen. Die Gesamthaftung der ${esc(ORG.name)}-Parteien ist in jedem Fall auf den höheren Betrag von 100 CAD oder dem Betrag, den Sie uns in den 12 Monaten vor dem Anspruch für die Nutzung gezahlt haben, begrenzt. Dies gilt nicht für Haftung, die gesetzlich nicht beschränkt werden kann, etwa bei Vorsatz, grober Fahrlässigkeit oder der Verletzung von Leben, Körper oder Gesundheit. Sie stellen die ${esc(ORG.name)}-Parteien von Ansprüchen, Verlusten und Kosten einschließlich Anwaltskosten frei, die aus Ihrem Verstoß gegen diese Bedingungen, Ihrem Missbrauch von Find My Trial™, von Ihnen übermittelten Inhalten oder Ihrem Verstoß gegen Gesetze oder Rechte Dritter entstehen.</li>
<li><b>Änderungen.</b> Wir können Find My Trial™ jederzeit ohne Ankündigung ändern, aussetzen, ersetzen oder einstellen. Wir können diese Bedingungen aktualisieren und ändern dann das Gültigkeitsdatum oben. Wenn Sie Find My Trial™ nach einer Aktualisierung weiter nutzen, akzeptieren Sie die neuen Bedingungen.</li>
<li><b>Allgemeines.</b>
 <ul><li>Sie bestätigen, dass Sie an Ihrem Wohnort volljährig sind und diesen Bedingungen rechtswirksam zustimmen können. Andernfalls nutzen Sie Find My Trial™ nur mit einem Elternteil oder Vormund, der diesen Bedingungen zustimmt.</li>
 <li>Die Nennung einer Studie, eines Sponsors, Krankenhauses oder Arzneimittels ist keine Empfehlung. ${esc(ORG.name)} ist nicht verbunden mit ${COUNTRY.notAffiliated[2]} oder einem darin genannten Krankenhaus, einer Universität, Forschungsgruppe oder einem Unternehmen, und Find My Trial™ wird von ihnen nicht unterstützt.</li>
 <li>Kontaktangaben von Studienteams werden so angezeigt, wie sie im Register stehen. Wir kontaktieren keine Studienteams für Sie und geben keine Daten weiter. Links zu anderen Websites dienen der Bequemlichkeit; für deren Inhalte und Praktiken sind wir nicht verantwortlich.</li>
 <li>Sollte ein Teil dieser Bedingungen unwirksam sein, bleibt der Rest wirksam.</li>
 <li>Diese Bedingungen bilden zusammen mit den Seiten „Datenschutz“ und „Datenquellen“ die gesamte Vereinbarung zwischen Ihnen und uns über Find My Trial™.</li>
 <li>Diese Bedingungen unterliegen dem Recht der Provinz Ontario und dem dort geltenden kanadischen Bundesrecht, unter Ausschluss der Kollisionsnormen; zwingende Verbraucherschutzvorschriften Ihres Wohnsitzlandes bleiben unberührt.</li></ul></li>
<li><b>Ihre Bestätigung.</b> Mit dem Ankreuzen des Kästchens oder der Nutzung von Find My Trial™ bestätigen Sie, dass Sie diese Bedingungen gelesen haben, verstehen, dass Find My Trial™ ein Pilotdienst mit möglichen Fehlern ist, sich nicht ohne eigene Prüfung und Rücksprache mit Ihrem Behandlungsteam auf seine Ergebnisse verlassen und diesen Bedingungen zustimmen.</li>
</ol>
<p><b>Kontakt:</b> ${esc(ORG.name)}, ${contactHTML()}</p>`,
privacy: () => `<h2>Datenschutz</h2><p class="lede">Stand: 22. November 2026.</p><ol>
<li><b>Ihre Antworten bleiben auf Ihrem Gerät.</b> Die Seite filtert die Studienliste in Ihrem Browser. Ihre Antworten werden weder an ${esc(ORG.name)} noch an andere gesendet und nicht gespeichert. Schließen oder Neuladen der Seite löscht sie.</li>
<li><b>Ihr Standort.</b> Wenn Sie „Meinen Standort verwenden“ wählen, fragt Ihr Browser um Erlaubnis und gibt der Seite dann Ihre ungefähre Position. Entfernungen werden auf Ihrem Gerät berechnet. Ihr Standort wird weder gesendet noch gespeichert.</li>
<li><b>Keine Konten, Cookies oder Tracking.</b> Die Seite fragt nicht nach Namen, Versicherungsnummer oder Kontaktdaten. Sie setzt keine Cookies und verwendet keine Analyse-, Werbe- oder Tracking-Skripte.</li>
<li><b>Studiendaten.</b> Ihr Browser lädt die Studienliste und die Studiendetails von dieser Website. Diese Anfragen enthalten nie Ihre Antworten.</li>
<li><b>Die Karte.</b> Für die Straßenkarte lädt Ihr Browser Kartenbilder von ${mapName()}. Dieser Dienst erhält bei jeder Anfrage Ihre IP-Adresse und Browserangaben nach seiner eigenen Datenschutzerklärung, möglicherweise auch außerhalb der EU, aber nie Ihre Antworten oder Ihren genauen Standort.</li>
<li><b>Links, die Sie öffnen.</b> Links zu ClinicalTrials.gov und Google Maps öffnen diese Websites mit ihren eigenen Datenschutzerklärungen. Ein Kartenlink enthält nur Name und Stadt des Studienzentrums.</li>
<li><b>Kopieren der Zusammenfassung.</b> Wenn Sie die Zusammenfassung kopieren, landet sie in der Zwischenablage Ihres Geräts. Was Sie danach damit tun, entscheiden Sie.</li>
<li><b>Der Webhoster.</b> Diese Seite wird auf GitHub Pages betrieben. Wie jeder Webhoster kann GitHub einfache Zugriffsprotokolle wie IP-Adresse und Browsertyp nach seiner eigenen Datenschutzerklärung führen.</li>
<li><b>Kontakt mit einem Studienteam.</b> Wenn Sie ein Studienteam kontaktieren, behandelt es Ihre Daten nach seinen eigenen Regeln und ${L(COUNTRY.privacyLaw, 2)}.</li>
<li><b>Fragen und Ihre Rechte.</b> ${contactHTML()}. Sie können sich auch bei der Datenschutzaufsichtsbehörde Ihres Landes beschweren.</li></ol>`,
data: () => `<h2>Datenquellen</h2><ol>
<li><b>Herkunft der Daten.</b> Studieneinträge, einschließlich Namen, Status und Kontakten der Zentren, werden einmal täglich von ClinicalTrials.gov heruntergeladen, einem Dienst der U.S. National Library of Medicine. Letzter Download: ${built()}. ClinicalTrials.gov und die National Library of Medicine unterstützen diese Seite nicht und haben die Angaben nicht geprüft.${XSRC(2)}</li>
<li><b>Welche Studien enthalten sind.</b> Jede Studie auf ClinicalTrials.gov ${L(A.about, 2)}, die rekrutiert oder bald rekrutiert und mindestens ein Zentrum ${COUNTRY.inName[2]} angibt${META ? ` (${META.studies} Studien an ${META.sites} Zentren beim letzten Download)` : ""}. ${LSRC(2, 'Studien, die nur in anderen Registern stehen, etwa im EU-Register CTIS oder im Deutschen Register Klinischer Studien (DRKS), sind noch nicht enthalten.')}</li>
<li><b>Zuordnung.</b> ${L(A.tagged, 2)} automatisch aus Titel, angegebenen Erkrankungen und den medizinischen Schlagwörtern des Registers erkannt${A.stage ? ", sowie aus den Einschlusskriterien" : ""}. Manche Studien haben mehrere Zuordnungen, und manche sind falsch.</li>
<li><b>Status der Zentren.</b> Jedes Zentrum zeigt den Status laut Register: rekrutiert, bald („Bald“), rekrutiert nicht, nur auf Einladung, unterbrochen oder geschlossen. Eine Studie kann insgesamt rekrutieren, während ein einzelnes Zentrum es nicht tut.</li>
<li><b>Kontakte.</b> Wo das Register einen Kontakt für ein Zentrum angibt, wird er angezeigt. Andernfalls wird der Hauptkontakt der Studie angezeigt, der in einem anderen Land sein kann.</li>
<li><b>Karte und Entfernungen.</b> Das Register gibt für jedes Zentrum den Ort der Stadt an, nicht die Adresse. Die Karte zeigt daher eine Markierung pro Stadt, und Entfernungen werden zwischen Städten gemessen.</li>
<li><b>Teilnahmekriterien.</b> Alters- und Geschlechtsgrenzen stammen aus den Feldern des Registers. Die vollständigen Kriterien werden wie im Register (auf Englisch) angezeigt. Viele Kriterien, etwa frühere Behandlungen, Laborwerte und andere Erkrankungen, werden nicht automatisch geprüft.</li>
<li><b>Statuswarnungen.</b> Eine Studie wird als „Status unsicher“ markiert, wenn ihr geschätztes Abschlussdatum vorbei ist oder ihr Eintrag seit mehr als 12 Monaten nicht aktualisiert wurde.</li>
<li><b>Kartennachweis.</b> Kartendaten © OpenStreetMap-Mitwirkende${MAP.mapboxToken ? "; Kartenstil © Mapbox" : ""}. Die Karte nutzt die quelloffene Bibliothek Leaflet.</li></ol>`};

  LEGAL.it = {
terms: () => `<h2>Condizioni d'uso</h2>
<p class="lede"><b>In vigore dal 23 novembre 2026.</b> Leggi attentamente queste condizioni. In caso di differenze tra le versioni linguistiche prevale la versione inglese.</p>
<p>Find My Trial™ è un servizio di ricerca di studi clinici gestito da ${esc(ORG.name)} («noi»), offerto attualmente in versione pilota. Spuntando la casella nella pagina iniziale, o accedendo a Find My Trial™ o usandolo, confermi di aver letto, compreso e accettato queste condizioni. Se non le accetti, non usare Find My Trial™.</p>
<ol>
<li><b>Che cos'è Find My Trial™.</b> Find My Trial™ è un servizio pilota. È aperto a privati, aziende e altre organizzazioni ed è in continuo miglioramento: alcune funzioni possono essere aggiunte, modificate o rimosse senza preavviso. È uno strumento informativo per trovare studi clinici da discutere con un medico o con il gruppo dello studio e non deve essere l'unica base per decisioni mediche, terapeutiche, di ricerca, legali o comunque importanti. Elenca gli studi ${L(A.about, 3)} che reclutano o reclutano a breve e hanno almeno un centro ${COUNTRY.inName[3]}, come pubblicati su ${REGS(3)}. L'elenco è aggiornato automaticamente una volta al giorno e la pagina mostra la data dell'ultimo aggiornamento. Gli studi non registrati su ${REGS(3)} non sono inclusi, quindi l'elenco può essere incompleto e i dettagli di uno studio possono essere cambiati dall'ultimo aggiornamento.</li>
<li><b>Servizio pilota e rischi.</b> Possiamo limitare, sospendere o interrompere l'accesso a Find My Trial™ in qualsiasi momento, con o senza preavviso. Usandolo accetti che
 <ul><li>essendo un servizio pilota, può contenere errori, difetti o funzioni incomplete;</li>
 <li>può mostrare informazioni errate, incomplete, fuorvianti o non aggiornate;</li>
 <li>può non essere disponibile in qualsiasi momento; e</li>
 <li>possiamo modificarlo, sospenderlo o smettere di offrirlo, e l'assistenza è a nostra discrezione salvo diverso accordo scritto.</li></ul>
 <b>Usi Find My Trial™ a tuo rischio.</b></li>
<li><b>Nessun parere medico, legale o professionale.</b> Find My Trial™ non fornisce pareri medici, clinici, scientifici, legali, regolatori o professionali. Corrispondenze, ordinamenti, riepiloghi e altri risultati hanno solo scopo informativo. Una corrispondenza non significa che tu possa partecipare a uno studio, e un'esclusione non significa che tu non sia idoneo: solo il gruppo dello studio può decidere, dopo aver esaminato la tua storia clinica completa e il protocollo completo. Find My Trial™ non raccomanda né sostiene alcuno studio, e le informazioni possono non essere aggiornate. Sei responsabile di verificare ciò che leggi prima di agire. <b>Parla sempre con il tuo medico o con un altro professionista sanitario qualificato prima di qualsiasi decisione su uno studio clinico o sulle tue cure.</b> Find My Trial™ non può rispondere alle emergenze: in caso di sintomi urgenti chiama il ${em()} o vai al pronto soccorso più vicino. ${sup(3)} ${cri(3)}</li>
<li><b>Abbinamento automatico e contenuti assistiti dall'IA.</b> Find My Trial™ filtra gli studi in base alle informazioni del registro e a regole automatiche fisse. ${L(A.tagged, 3)} automaticamente dal testo del registro e possono essere errati. Dove Find My Trial™ mostra una verifica personale dei criteri, questi sono stati letti da strumenti di intelligenza artificiale e non sono stati esaminati da un clinico. Risultati e contenuti possono quindi essere errati, incompleti, non aggiornati o incoerenti e non vanno usati senza verificare la scheda originale del registro e parlare con il gruppo dello studio. Non garantiamo che risultati o contenuti siano accurati, completi, affidabili o adatti alle tue esigenze, e non sosteniamo alcun servizio, prodotto o terapia.</li>
<li><b>Uso consentito.</b> Ti impegni a non
 <ul><li>usare Find My Trial™ per scopi illeciti;</li>
 <li>tentare di accedere senza autorizzazione ad account, sistemi o dati collegati;</li>
 <li>introdurre virus, malware o altro codice dannoso;</li>
 <li>interferire con il suo funzionamento o aggirare controlli di accesso o limiti tecnici;</li>
 <li>decodificarlo, decompilarlo o disassemblarlo, salvo ove la legge lo consenta o con nostro permesso scritto;</li>
 <li>estrarne o copiarne sistematicamente i dati, o usare bot o strumenti automatici, senza nostro permesso scritto;</li>
 <li>effettuare test di sicurezza, vulnerabilità o penetrazione senza nostro permesso scritto; o</li>
 <li>usarlo in modo che possa comprometterne sicurezza, integrità o disponibilità.</li></ul></li>
<li><b>Commenti.</b> Accogliamo commenti, suggerimenti, segnalazioni di errori e altri riscontri («Feedback») all'indirizzo ${contactHTML()}. Sei responsabile di ciò che ci invii e confermi di avere il diritto di condividerlo. Ci concedi una licenza perpetua, irrevocabile, mondiale, gratuita, trasferibile e sublicenziabile per usare, copiare, modificare, condividere e sfruttare il Feedback, anche a fini commerciali, senza compenso, citazione o ulteriore autorizzazione. Non includere dati sanitari o altri dati personali sensibili. I dati personali che decidi di includere sono trattati come descritto nella sezione 7.</li>
<li><b>Privacy.</b> Le tue risposte alle domande di Find My Trial™, e la tua posizione se scegli «Usa la mia posizione», sono trattate solo nel tuo browser. Non le raccogliamo, conserviamo o riceviamo, e non sono inviate ad alcun servizio di intelligenza artificiale. Per mostrare la mappa stradale, il tuo browser richiede immagini al nostro fornitore di mappe, che riceve il tuo indirizzo IP e i dati del browser secondo la propria informativa, ma mai le tue risposte. Se ci invii Feedback che ti identifica, accetti che lo raccogliamo, usiamo, conserviamo ed esaminiamo per valutare, mantenere, correggere e migliorare Find My Trial™, sviluppare nuove funzioni, per ricerca interna e controlli di qualità e per documentare il progetto pilota. La pagina «Privacy» fornisce maggiori dettagli.</li>
<li><b>Proprietà intellettuale.</b> Design, testi, codice e materiali correlati di Find My Trial™ appartengono a ${esc(ORG.name)} o ai suoi licenzianti e sono protetti dalla legge. Le informazioni sugli studi appartengono al registro e ai promotori. Dati cartografici © collaboratori di OpenStreetMap${MAP.mapboxToken ? ", stile della mappa © Mapbox" : ""}; la mappa usa la libreria open source Leaflet con la propria licenza. Nessuna proprietà ti viene trasferita. Nel rispetto di queste condizioni, ti concediamo un diritto limitato, revocabile, non esclusivo e non trasferibile di usare Find My Trial™ per cercare e consultare informazioni sugli studi clinici, per te stesso o all'interno della tua azienda o organizzazione, anche per scopi commerciali. Rivendere, ripubblicare o ridistribuire Find My Trial™ o i suoi contenuti, o usarli per creare un altro prodotto, servizio o insieme di dati, richiede un accordo scritto separato con noi. <b>Ricerca e citazione.</b> Se usi informazioni trovate tramite Find My Trial™ in una ricerca, una pubblicazione, un rapporto o una presentazione, devi citarle così: «Fonte: Find My Trial™, Salish Seven LLC (consultato il [data])», insieme ai registri originali degli studi. La selezione, l'organizzazione, la classificazione e la traduzione delle informazioni sugli studi sono opera di Salish Seven LLC, che ne resta autrice e proprietaria; il loro uso non ti trasferisce tale paternità né tale proprietà. L'estrazione o l'analisi massiva dei dati di Find My Trial™ a fini di ricerca richiede un accordo scritto con noi.</li>
<li><b>Informazioni riservate.</b> Se ti condividiamo direttamente materiale non pubblico, come nuove funzioni, documenti o dati di prestazione forniti ai partecipanti al progetto pilota o ai partner commerciali, ti impegni a non divulgarlo senza il nostro consenso scritto. Ciò non vale per informazioni che diventano pubbliche senza violazione di queste condizioni, che conoscevi legittimamente prima o che sei tenuto per legge a divulgare.</li>
<li><b>Sospensione e cessazione.</b> Possiamo sospendere o interrompere il tuo accesso in qualsiasi momento, con o senza preavviso. Alla cessazione, il tuo diritto di usare Find My Trial™ termina immediatamente. Le sezioni 6, 8, 9, 11, 12 e 14 continuano ad applicarsi.</li>
<li><b>Nessuna garanzia.</b> Find My Trial™ è fornito «così com'è», «come disponibile» e «con tutti i difetti». Non diamo garanzie, esplicite o implicite, che sia accurato, completo, privo di errori, sicuro, privo di difetti o adatto a uno scopo particolare. Restano salvi i diritti inderogabili che la legge ti riconosce come consumatore.</li>
<li><b>Limitazione di responsabilità e manleva.</b> Nella misura massima consentita dalla legge, ${esc(ORG.name)} e i suoi amministratori, dirigenti, membri, volontari, collaboratori, agenti e licenzianti (le «Parti ${esc(ORG.name)}») non sono responsabili per danni diretti, indiretti, speciali, incidentali o consequenziali di alcun tipo, compresi mancati guadagni o altre perdite economiche, derivanti dall'uso o dall'impossibilità di usare Find My Trial™ o i siti collegati. In ogni caso la responsabilità complessiva delle Parti ${esc(ORG.name)} è limitata al maggiore tra 100 CAD e l'importo che ci hai pagato per usare Find My Trial™ nei 12 mesi precedenti la richiesta. Ciò non si applica alla responsabilità che la legge non consente di limitare, come in caso di dolo o colpa grave o di danni alla vita o alla salute. Ti impegni a tenere indenni le Parti ${esc(ORG.name)} da responsabilità, perdite, danni e costi, comprese le spese legali, derivanti dalla tua violazione di queste condizioni, dall'uso improprio di Find My Trial™, dai contenuti che invii o dalla violazione di leggi o diritti altrui.</li>
<li><b>Modifiche.</b> Possiamo modificare, sospendere, sostituire o interrompere Find My Trial™ in qualsiasi momento senza preavviso. Possiamo aggiornare queste condizioni e in tal caso modificheremo la data di entrata in vigore indicata sopra. Se continui a usare Find My Trial™ dopo un aggiornamento, accetti le condizioni aggiornate.</li>
<li><b>Disposizioni generali.</b>
 <ul><li>Confermi di aver raggiunto la maggiore età nel luogo in cui vivi e di poter accettare legalmente queste condizioni. In caso contrario, usa Find My Trial™ solo con un genitore o tutore che le accetti.</li>
 <li>L'indicazione di uno studio, promotore, ospedale o medicinale non è una raccomandazione. ${esc(ORG.name)} non è affiliato a ${COUNTRY.notAffiliated[3]} né ad alcun ospedale, università, gruppo di ricerca o azienda citati, e Find My Trial™ non è approvato da loro.</li>
 <li>I contatti dei gruppi di studio sono mostrati come riportati nel registro. Non contattiamo i gruppi di studio per tuo conto e non trasmettiamo le tue informazioni. I link ad altri siti sono forniti per comodità e non siamo responsabili dei loro contenuti o pratiche.</li>
 <li>Se una parte di queste condizioni risulta invalida, il resto rimane pienamente efficace.</li>
 <li>Queste condizioni, insieme alle pagine «Privacy» e «Fonti dei dati», costituiscono l'intero accordo tra te e noi su Find My Trial™.</li>
 <li>Queste condizioni sono regolate dalle leggi della Provincia dell'Ontario e dalle leggi federali canadesi ivi applicabili, escluse le norme sui conflitti di leggi; restano salve le norme imperative a tutela dei consumatori del tuo paese di residenza.</li></ul></li>
<li><b>La tua conferma.</b> Spuntando la casella o usando Find My Trial™ confermi di aver letto queste condizioni, di capire che Find My Trial™ è un servizio pilota che può contenere errori, di non fare affidamento sui suoi risultati senza verificarli e parlarne con la tua équipe di cura e di accettare queste condizioni.</li>
</ol>
<p><b>Contatto:</b> ${esc(ORG.name)}, ${contactHTML()}</p>`,
privacy: () => `<h2>Privacy</h2><p class="lede">Ultimo aggiornamento: 22 novembre 2026.</p><ol>
<li><b>Le tue risposte restano sul tuo dispositivo.</b> La pagina filtra l'elenco degli studi nel tuo browser. Le tue risposte non sono inviate a ${esc(ORG.name)} né ad altri e non sono salvate. Chiudere o ricaricare la pagina le cancella.</li>
<li><b>La tua posizione.</b> Se scegli «Usa la mia posizione», il browser ti chiede il permesso e poi fornisce alla pagina la tua posizione approssimativa. Le distanze sono calcolate sul tuo dispositivo. La tua posizione non è inviata né salvata.</li>
<li><b>Nessun account, cookie o tracciamento.</b> La pagina non chiede nome, numero di tessera sanitaria o recapiti. Non imposta cookie e non usa script di analisi, pubblicità o tracciamento.</li>
<li><b>Dati degli studi.</b> Il tuo browser scarica l'elenco e i dettagli degli studi da questo sito. Queste richieste non contengono mai le tue risposte.</li>
<li><b>La mappa.</b> Per mostrare la mappa stradale, il tuo browser scarica immagini da ${mapName()}. Questo servizio riceve a ogni richiesta il tuo indirizzo IP e i dati del browser secondo la propria informativa, anche fuori dall'UE, ma mai le tue risposte o la tua posizione esatta.</li>
<li><b>Link che scegli di aprire.</b> I link a ClinicalTrials.gov e Google Maps aprono questi siti, con le loro informative. Un link alla mappa contiene solo il nome e la città del centro.</li>
<li><b>Copia del riepilogo.</b> Se copi il riepilogo, finisce negli appunti del tuo dispositivo. Cosa farne dopo spetta a te.</li>
<li><b>L'hosting.</b> Questa pagina è ospitata su GitHub Pages. Come ogni servizio di hosting, GitHub può conservare registri di accesso di base, come indirizzo IP e tipo di browser, secondo la propria informativa.</li>
<li><b>Contatto con un gruppo di studio.</b> Se contatti un gruppo di studio, tratterà i tuoi dati secondo le proprie pratiche e ${L(COUNTRY.privacyLaw, 3)}.</li>
<li><b>Domande e diritti.</b> ${contactHTML()}. Puoi anche presentare reclamo all'autorità per la protezione dei dati del tuo paese.</li></ol>`,
data: () => `<h2>Fonti dei dati</h2><ol>
<li><b>Da dove provengono i dati.</b> Le schede degli studi, compresi nomi, stato e contatti dei centri, sono scaricate una volta al giorno da ClinicalTrials.gov, un servizio della U.S. National Library of Medicine. Ultimo download: ${built()}. ClinicalTrials.gov e la National Library of Medicine non sostengono questa pagina e non hanno verificato le informazioni.${XSRC(3)}</li>
<li><b>Quali studi sono inclusi.</b> Ogni studio su ClinicalTrials.gov ${L(A.about, 3)} che recluta o recluterà a breve e indica almeno un centro ${COUNTRY.inName[3]}${META ? ` (${META.studies} studi in ${META.sites} centri all'ultimo download)` : ""}. ${LSRC(3, 'Gli studi presenti solo in altri registri, come il registro europeo CTIS, non sono ancora inclusi.')}</li>
<li><b>Classificazione.</b> ${L(A.tagged, 3)} automaticamente dal titolo, dalle malattie indicate e dai descrittori medici del registro${A.stage ? ", oltre che dai criteri di inclusione" : ""}. Alcuni studi hanno più classificazioni e alcune saranno errate.</li>
<li><b>Stato dei centri.</b> Ogni centro mostra lo stato indicato nel registro: recluta, presto, non recluta, solo su invito, sospeso o chiuso. Uno studio può reclutare nel complesso mentre un singolo centro no.</li>
<li><b>Contatti.</b> Quando il registro indica un contatto per un centro, viene mostrato. Altrimenti è mostrato il contatto principale dello studio, che può trovarsi in un altro paese.</li>
<li><b>Mappa e distanze.</b> Il registro indica per ogni centro la posizione della città, non l'indirizzo, quindi la mappa mostra un segnaposto per città e le distanze sono misurate tra città.</li>
<li><b>Criteri di partecipazione.</b> I limiti di età e sesso provengono dai campi del registro. I criteri completi sono mostrati come nel registro (in inglese). Molti criteri, come trattamenti precedenti, esami e altre malattie, non sono verificati automaticamente.</li>
<li><b>Avvisi sullo stato.</b> Uno studio è indicato come «stato incerto» quando la data prevista di completamento è passata o la scheda non è aggiornata da più di 12 mesi.</li>
<li><b>Crediti della mappa.</b> Dati cartografici © collaboratori di OpenStreetMap${MAP.mapboxToken ? "; stile della mappa © Mapbox" : ""}. La mappa usa la libreria open source Leaflet.</li></ol>`};

  LEGAL.es = {
terms: () => `<h2>Condiciones de uso</h2>
<p class="lede"><b>Vigentes desde el 23 de noviembre de 2026.</b> Lea atentamente estas condiciones. Si las versiones lingüísticas difieren, prevalece la versión inglesa.</p>
<p>Find My Trial™ es un servicio de búsqueda de ensayos clínicos gestionado por ${esc(ORG.name)} («nosotros»), que se ofrece actualmente como piloto. Al marcar la casilla de la página de inicio, o al acceder a Find My Trial™ o usarlo, confirma que ha leído, entendido y aceptado estas condiciones. Si no las acepta, no use Find My Trial™.</p>
<ol>
<li><b>Qué es Find My Trial™.</b> Find My Trial™ es un servicio piloto. Está abierto a particulares, empresas y otras organizaciones y se sigue mejorando, por lo que pueden añadirse, cambiarse o retirarse funciones sin aviso. Es una herramienta informativa para encontrar ensayos clínicos que comentar con un médico o un equipo de estudio, y no debe ser la única base para decisiones médicas, terapéuticas, de investigación, legales u otras decisiones importantes. Muestra los estudios ${L(A.about, 4)} que reclutan o reclutarán próximamente y tienen al menos un centro ${COUNTRY.inName[4]}, tal como se publican en ${REGS(4)}. La lista se actualiza automáticamente una vez al día y la página muestra la fecha de la última actualización. Los estudios no registrados en ${REGS(4)} no se incluyen, por lo que la lista puede estar incompleta, y los datos de un estudio pueden haber cambiado desde la última actualización.</li>
<li><b>Servicio piloto y riesgos.</b> Podemos limitar, suspender o terminar el acceso a Find My Trial™ en cualquier momento, con o sin aviso. Al usarlo, acepta que
 <ul><li>al ser un servicio piloto, puede contener errores, defectos o funciones incompletas;</li>
 <li>puede mostrar información incorrecta, incompleta, engañosa o desactualizada;</li>
 <li>puede no estar disponible en cualquier momento; y</li>
 <li>podemos cambiarlo, pausarlo o dejar de ofrecerlo, y el soporte queda a nuestra discreción salvo acuerdo escrito en contrario.</li></ul>
 <b>Usa Find My Trial™ bajo su propio riesgo.</b></li>
<li><b>No es consejo médico, legal ni profesional.</b> Find My Trial™ no ofrece consejo médico, clínico, científico, legal, regulatorio ni profesional. Las coincidencias, ordenaciones, resúmenes y demás resultados son solo informativos. Una coincidencia no significa que pueda participar en un estudio, y una exclusión no significa que no sea elegible: solo el equipo del estudio puede decidirlo, tras revisar su historia clínica completa y el protocolo completo. Find My Trial™ no recomienda ni respalda ningún ensayo, y la información puede estar desactualizada. Usted es responsable de comprobar lo que lea antes de actuar. <b>Hable siempre con su médico u otro profesional sanitario cualificado antes de tomar cualquier decisión sobre un ensayo clínico o su tratamiento.</b> Find My Trial™ no puede atender urgencias: si tiene síntomas urgentes, llame al ${em()} o acuda al servicio de urgencias más cercano. ${sup(4)} ${cri(4)}</li>
<li><b>Clasificación automática y contenido asistido por IA.</b> Find My Trial™ filtra los estudios con la información del registro y reglas automáticas fijas. ${L(A.tagged, 4)} automáticamente a partir del texto del registro y pueden ser erróneos. Cuando Find My Trial™ muestra una comprobación personal de los criterios, estos los han leído herramientas de inteligencia artificial y no los ha revisado un clínico. Por tanto, los resultados y el contenido pueden ser incorrectos, incompletos, desactualizados o incoherentes, y no deben usarse sin comprobar la ficha original del registro y hablar con el equipo del estudio. No garantizamos que ningún resultado o contenido sea exacto, completo, fiable o adecuado para sus necesidades, y no respaldamos ningún servicio, producto ni tratamiento.</li>
<li><b>Uso aceptable.</b> Se compromete a no
 <ul><li>usar Find My Trial™ con fines ilícitos;</li>
 <li>intentar acceder sin autorización a cuentas, sistemas o datos relacionados;</li>
 <li>introducir virus, malware u otro código dañino;</li>
 <li>interferir en su funcionamiento ni eludir controles de acceso o límites técnicos;</li>
 <li>aplicar ingeniería inversa, descompilarlo o desensamblarlo, salvo que la ley lo permita o lo autoricemos por escrito;</li>
 <li>extraer o copiar sistemáticamente sus datos, ni usar bots o herramientas automáticas, sin nuestra autorización escrita;</li>
 <li>realizar pruebas de seguridad, vulnerabilidad o penetración sin nuestra autorización escrita; ni</li>
 <li>usarlo de forma que pueda dañar su seguridad, integridad o disponibilidad.</li></ul></li>
<li><b>Comentarios.</b> Agradecemos comentarios, sugerencias, informes de errores y otras aportaciones («Comentarios») en ${contactHTML()}. Usted es responsable de lo que nos envíe y confirma que tiene derecho a compartirlo. Nos concede una licencia perpetua, irrevocable, mundial, gratuita, transferible y sublicenciable para usar, copiar, modificar, compartir y aprovechar los Comentarios, incluso con fines comerciales, sin pago, mención ni permiso adicional. No incluya datos de salud ni otros datos personales sensibles. Los datos personales que decida incluir se tratarán como se describe en el apartado 7.</li>
<li><b>Privacidad.</b> Sus respuestas a las preguntas de Find My Trial™, y su ubicación si elige «Usar mi ubicación», se procesan solo en su navegador. No las recogemos, guardamos ni recibimos, y no se envían a ningún servicio de inteligencia artificial. Para mostrar el mapa, su navegador solicita imágenes a nuestro proveedor de mapas, que recibe su dirección IP y los datos del navegador según su propia política de privacidad, pero nunca sus respuestas. Si nos envía Comentarios que le identifiquen, acepta que los recojamos, usemos, guardemos y revisemos para evaluar, mantener, corregir y mejorar Find My Trial™, desarrollar nuevas funciones, para investigación interna y controles de calidad y para documentar el proyecto piloto. La página «Privacidad» ofrece más detalles.</li>
<li><b>Propiedad intelectual.</b> El diseño, los textos, el código y los materiales de Find My Trial™ pertenecen a ${esc(ORG.name)} o a sus licenciantes y están protegidos por la ley. La información de los ensayos pertenece a su registro y promotores. Datos del mapa © colaboradores de OpenStreetMap${MAP.mapboxToken ? ", estilo del mapa © Mapbox" : ""}; el mapa usa la biblioteca de código abierto Leaflet con su propia licencia. No se le transfiere ninguna propiedad. Con sujeción a estas condiciones, le concedemos un derecho limitado, revocable, no exclusivo e intransferible a usar Find My Trial™ para buscar y consultar información sobre ensayos clínicos, para usted o dentro de su empresa u organización, incluso con fines comerciales. Revender, volver a publicar o redistribuir Find My Trial™ o su contenido, o usarlo para crear otro producto, servicio o conjunto de datos, requiere un acuerdo escrito aparte con nosotros. <b>Investigación y cita.</b> Si usa información encontrada a través de Find My Trial™ en una investigación, una publicación, un informe o una presentación, debe citarla así: «Fuente: Find My Trial™, Salish Seven LLC (consultado el [fecha])», junto con los registros de ensayos originales. La selección, organización, clasificación y traducción de la información de los ensayos son obra de Salish Seven LLC, que sigue siendo su autora y propietaria; su uso no le transfiere esa autoría ni esa propiedad. La extracción o el análisis masivo de datos de Find My Trial™ con fines de investigación requiere un acuerdo escrito con nosotros.</li>
<li><b>Información confidencial.</b> Si le compartimos directamente material no público, como nuevas funciones, documentos o datos de rendimiento para participantes en el piloto o socios comerciales, se compromete a no divulgarlo sin nuestro consentimiento escrito. Esto no se aplica a información que se haga pública sin incumplir estas condiciones, que ya conociera legítimamente o que deba divulgar por ley.</li>
<li><b>Suspensión y terminación.</b> Podemos suspender o terminar su acceso en cualquier momento, con o sin aviso. Al terminar el acceso, su derecho a usar Find My Trial™ termina de inmediato. Los apartados 6, 8, 9, 11, 12 y 14 siguen aplicándose.</li>
<li><b>Sin garantías.</b> Find My Trial™ se ofrece «tal cual», «según disponibilidad» y «con todos sus defectos». No garantizamos, ni expresa ni implícitamente, que sea exacto, completo, libre de errores, seguro, sin defectos o adecuado para un fin concreto. Quedan a salvo los derechos irrenunciables que la ley le reconoce como consumidor.</li>
<li><b>Limitación de responsabilidad e indemnización.</b> En la máxima medida permitida por la ley, ${esc(ORG.name)} y sus administradores, directivos, miembros, voluntarios, colaboradores, agentes y licenciantes (las «Partes de ${esc(ORG.name)}») no responden de daños directos, indirectos, especiales, incidentales o consecuentes de ningún tipo, incluido el lucro cesante u otras pérdidas económicas, derivados del uso o la imposibilidad de usar Find My Trial™ o sitios enlazados. En todo caso, la responsabilidad total de las Partes de ${esc(ORG.name)} se limita a la mayor de estas cantidades: 100 CAD o lo que usted nos haya pagado por usar Find My Trial™ en los 12 meses anteriores a la reclamación. Esto no se aplica a la responsabilidad que la ley no permite limitar, como en caso de dolo, culpa grave o daños a la vida o la salud. Se compromete a indemnizar a las Partes de ${esc(ORG.name)} por responsabilidades, pérdidas, daños y gastos, incluidos honorarios legales, derivados de su incumplimiento de estas condiciones, el mal uso de Find My Trial™, el contenido que envíe o la vulneración de leyes o derechos de terceros.</li>
<li><b>Cambios.</b> Podemos cambiar, suspender, sustituir o interrumpir Find My Trial™ en cualquier momento sin aviso. Podemos actualizar estas condiciones y, si lo hacemos, cambiaremos la fecha de vigencia indicada arriba. Si sigue usando Find My Trial™ tras una actualización, acepta las condiciones actualizadas.</li>
<li><b>Disposiciones generales.</b>
 <ul><li>Confirma que es mayor de edad en su lugar de residencia y puede aceptar legalmente estas condiciones. Si no lo es, use Find My Trial™ solo con un padre, madre o tutor que las acepte.</li>
 <li>Mostrar un estudio, promotor, hospital o medicamento no es una recomendación. ${esc(ORG.name)} no tiene relación con ${COUNTRY.notAffiliated[4]} ni con ningún hospital, universidad, grupo de investigación o empresa mencionados, y Find My Trial™ no cuenta con su respaldo.</li>
 <li>Los contactos de los equipos de estudio se muestran tal como figuran en el registro. No contactamos con los equipos por usted ni les transmitimos sus datos. Los enlaces a otros sitios se ofrecen por comodidad y no somos responsables de su contenido ni prácticas.</li>
 <li>Si alguna parte de estas condiciones resulta inválida, el resto sigue en vigor.</li>
 <li>Estas condiciones, junto con las páginas «Privacidad» y «Fuentes de datos», constituyen el acuerdo completo entre usted y nosotros sobre Find My Trial™.</li>
 <li>Estas condiciones se rigen por las leyes de la Provincia de Ontario y las leyes federales de Canadá aplicables allí, sin atender a normas de conflicto de leyes; quedan a salvo las normas imperativas de protección de los consumidores de su país de residencia.</li></ul></li>
<li><b>Su confirmación.</b> Al marcar la casilla o usar Find My Trial™ confirma que ha leído estas condiciones, entiende que Find My Trial™ es un servicio piloto que puede contener errores, no se basará en sus resultados sin comprobarlos y hablar con su equipo médico, y acepta estas condiciones.</li>
</ol>
<p><b>Contacto:</b> ${esc(ORG.name)}, ${contactHTML()}</p>`,
privacy: () => `<h2>Privacidad</h2><p class="lede">Última actualización: 22 de noviembre de 2026.</p><ol>
<li><b>Sus respuestas se quedan en su dispositivo.</b> La página filtra la lista de estudios en su navegador. Sus respuestas no se envían a ${esc(ORG.name)} ni a nadie más y no se guardan. Al cerrar o recargar la página se borran.</li>
<li><b>Su ubicación.</b> Si elige «Usar mi ubicación», el navegador le pide permiso y luego da a la página su posición aproximada. Las distancias se calculan en su dispositivo. Su ubicación no se envía ni se guarda.</li>
<li><b>Sin cuentas, cookies ni seguimiento.</b> La página no pide nombre, número de tarjeta sanitaria ni datos de contacto. No usa cookies ni scripts de análisis, publicidad o seguimiento.</li>
<li><b>Datos de los ensayos.</b> Su navegador descarga la lista y los detalles de los estudios desde este sitio. Esas solicitudes nunca incluyen sus respuestas.</li>
<li><b>El mapa.</b> Para mostrar el mapa, su navegador descarga imágenes de ${mapName()}. Ese servicio recibe en cada solicitud su dirección IP y los datos del navegador según su propia política de privacidad, también fuera de la UE, pero nunca sus respuestas ni su ubicación exacta.</li>
<li><b>Enlaces que decida abrir.</b> Los enlaces a ClinicalTrials.gov y Google Maps abren esos sitios, con sus propias políticas de privacidad. Un enlace al mapa contiene solo el nombre y la ciudad del centro.</li>
<li><b>Copiar el resumen.</b> Si copia el resumen, va al portapapeles de su dispositivo. Lo que haga después depende de usted.</li>
<li><b>El alojamiento.</b> Esta página está alojada en GitHub Pages. Como cualquier servicio de alojamiento, GitHub puede guardar registros básicos de visitas, como la dirección IP y el tipo de navegador, según su propia política.</li>
<li><b>Contacto con un equipo de estudio.</b> Si contacta con un equipo de estudio, tratará sus datos según sus propias prácticas y ${L(COUNTRY.privacyLaw, 4)}.</li>
<li><b>Preguntas y derechos.</b> ${contactHTML()}. También puede presentar una reclamación ante la autoridad de protección de datos de su país.</li></ol>`,
data: () => `<h2>Fuentes de datos</h2><ol>
<li><b>De dónde proceden los datos.</b> Las fichas de los estudios, incluidos nombres, estado y contactos de los centros, se descargan una vez al día de ClinicalTrials.gov, un servicio de la Biblioteca Nacional de Medicina de EE. UU. Última descarga: ${built()}. ClinicalTrials.gov y la Biblioteca Nacional de Medicina no respaldan esta página y no han revisado la información.${XSRC(4)}</li>
<li><b>Qué estudios se incluyen.</b> Todos los estudios de ClinicalTrials.gov ${L(A.about, 4)} que reclutan o reclutarán próximamente e indican al menos un centro ${COUNTRY.inName[4]}${META ? ` (${META.studies} estudios en ${META.sites} centros en la última descarga)` : ""}. ${LSRC(4, 'Los estudios registrados solo en otros registros, como el registro europeo CTIS o el Registro Español de Estudios Clínicos, aún no se incluyen.')}</li>
<li><b>Clasificación.</b> ${L(A.tagged, 4)} automáticamente a partir del título, las enfermedades indicadas y los descriptores médicos del registro${A.stage ? ", además de los criterios de inclusión" : ""}. Algunos estudios tienen varias clasificaciones y algunas serán erróneas.</li>
<li><b>Estado de los centros.</b> Cada centro muestra el estado que indica el registro: reclutando, próximamente, no recluta, solo por invitación, suspendido o cerrado. Un estudio puede estar reclutando en conjunto aunque un centro concreto no lo esté.</li>
<li><b>Contactos.</b> Si el registro indica un contacto para un centro, se muestra. Si no, se muestra el contacto principal del estudio, que puede estar en otro país.</li>
<li><b>Mapa y distancias.</b> El registro da para cada centro la ubicación de la ciudad, no la dirección, por lo que el mapa muestra un marcador por ciudad y las distancias se miden entre ciudades.</li>
<li><b>Criterios de participación.</b> Los límites de edad y sexo proceden de los campos del registro. Los criterios completos se muestran como en el registro (en inglés). Muchos criterios, como tratamientos previos, análisis y otras enfermedades, no se comprueban automáticamente.</li>
<li><b>Avisos de estado.</b> Un estudio se marca como «estado incierto» cuando su fecha prevista de finalización ya pasó o su ficha no se ha actualizado en más de 12 meses.</li>
<li><b>Créditos del mapa.</b> Datos del mapa © colaboradores de OpenStreetMap${MAP.mapboxToken ? "; estilo del mapa © Mapbox" : ""}. El mapa usa la biblioteca de código abierto Leaflet.</li></ol>`};
})();
